head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gUerId = js_id;
scwin.vScrenID = "ULDSTF30643.xml";
scwin.gLastJob = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_setHeader = function() {
    dts_Save.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DISCLS_PROFS_AHTH_INOUT";
    dts_Save.Reset();
    dts_Save.insertRow();
};


//담당자 검색
scwin.fn_Search = function() {
    if ($c.stf.getObjectValue(txb_isur_cd) == '') {
        $c.win.alert("[회사]를 선택해 주십시오");
        txb_com_abbrv.focus();
        return;
    }
    $c.cm.ShowWin(grd_Grid);
    var url = "/ListedCompany.do?method=listDisclsEduNattend";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd);
    url += "&EDU_KIND_CD=";
    url += "&YYYY=";
    url += "&EMP_NO=";
    url += "&DEP_CD=";
    url += "&CHRG_NM=" + $c.stf.getObjectValue(txb_chrg_nm);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_ComDisclsPerson.DataID = encodeURI(url);
    dts_ComDisclsPerson.Reset();
};
scwin.fn_check = function() {
    if (chb_insert_yn.checked == true) {
        var ISUR_NM = txb_com_abbrv.getValue(); //회사명
        var ISURCD = txb_isur_cd.getValue(); //회사명


        txb_sel_isur_nm.setValue(ISUR_NM);
        txb_hdn_isur_cd.setValue(ISURCD);

        //txb_sel_nm.value = "";
        //txb_jobtitl_nm.value ="";
        //txb_tel_no.value = "";

    }
};
scwin.fn_Save = function() {
    if ($c.stf.getObjectValue(txb_hdn_isur_cd) == '') {
        if ($c.stf.getObjectValue(chb_insert_yn) == 'Y') {
            $c.win.alert("[회사코드]를 입력해 주십시오");
        } else {
            $c.win.alert("[회사]를 조회해 주십시오");
        }
        txb_hdn_isur_cd.focus();
        return;
    }
    if ($c.stf.getObjectValue(txb_sel_nm) == '') {
        if ($c.stf.getObjectValue(chb_insert_yn) == 'Y') {
            $c.win.alert("[성명]를 입력해 주십시오");
        } else {
            $c.win.alert("[성명]를 선택해 주십시오");
        }
        txb_sel_nm.focus();
        return;
    }
    if ($c.stf.getObjectValue(cmb_sel_priz_rec) == '') {
        $c.win.alert("[표창여부]를 입력해 주십시오");
        cmb_sel_priz_rec.focus();
        return;
    }
    if ($c.stf.getObjectValue(txb_profs_ahth_no) == '') {
        $c.win.alert("[인증번호]를 입력해 주십시오");
        txb_profs_ahth_no.focus();
        return;
    }
    if ($c.stf.getObjectValue(txb_profs_ahth_rnd) == '') {
        $c.win.alert("[인증회차]를 입력해 주십시오");
        txb_profs_ahth_rnd.focus();
        return;
    }
    if ($c.stf.getObjectValue(edt_ahth_dd) == '') {
        $c.win.alert("[인증시기]를 입력해 주십시오");
        edt_ahth_dd.focus();
        return;
    }
    if ($c.stf.getObjectValue(cmb_sel_ahth_yn) == '') {
        $c.win.alert("[인증여부]를 입력해 주십시오");
        cmb_sel_ahth_yn.focus();
        return;
    }
    if (confirm('저장 하시겠습니까?')) {
        scwin.gLastJob = "저장";
        dts_Save.setCellData(1, "PROFS_CHRG_YN", scwin.fn_getCheckboxData(chb_insert_yn));
        trs_Save.Action = "/ListedCompany.do?method=saveDisclsProfAhth&USR_ID=" + scwin.gUerId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput1=dts_Save)";
        trs_Save.Post();
    }
};
scwin.fn_getCheckboxData = function(obj) {
    if (obj.checked) {
        return 'N';
    } else {
        return 'Y';
    }
};



// 저장 에러 발생 시
scwin.alert_error2 = function(dtsObj) {
    var USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (var i = 0; i < USER_DEFINE.length; i++) {
        var errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        var j;
        for (j = 0; j < errorCount; j++) {
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) == '0') {
                //'0' 임의로 떨군 INFO 메시지
                $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                //기존 에러 메시지
                $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};
scwin.dts_ComDisclsPerson_OnFail = function() {
    $c.stf.alert_error(dts_ComDisclsPerson);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_ComDisclsPerson_OnLoadError = function() {
    $c.stf.alert_error(dts_ComDisclsPerson);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_ComDisclsPerson_OnLoadCompleted = function(rowcount) {
    if (rowcount <= 0) {
        dts_ComDisclsPerson.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.grd_Grid_OnClick = function(row, colid) {
    var CHAR_NM = dts_ComDisclsPerson.getCellData(row, "CHRG_NM"); //담당자명
    var ISUR_NM = dts_ComDisclsPerson.getCellData(row, "COM_ABBRV"); //회사명
    var ISURCD = dts_ComDisclsPerson.getCellData(row, "ISUR_CD"); //회사명
    var JOBTITL = dts_ComDisclsPerson.getCellData(row, "JOBTITL_NM"); //직위
    var TLENO = dts_ComDisclsPerson.getCellData(row, "CELLPHONE_NO"); //전화번호

    txb_sel_nm.setValue(CHAR_NM);
    txb_sel_isur_nm.setValue(ISUR_NM);
    txb_hdn_isur_cd.setValue(ISURCD);
    if (JOBTITL == "") {
        txb_jobtitl_nm.setValue("-");
    } else {
        txb_jobtitl_nm.setValue(JOBTITL);
    }
    if (TLENO == "") {
        txb_tel_no.setValue("-");
    } else {
        txb_tel_no.setValue(TLENO);
    }
    chb_insert_yn.setValue(0);
};
scwin.grd_Grid_OnDblClick = function(row, colid) {

};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.txb_chrg_nm_onkeypress = function() {
    scwin.fn_Search(); //엔터키 입력시 조회 수행

};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_ahthCal_onclick = function() {
    popUpCalendar2(edt_ahth_dd);
};
scwin.chb_insert_yn_onclick = function() {
    scwin.fn_check();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.trs_Save_OnFail = function() {
    scwin.alert_error2(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    var msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
    $c.win.alert(msg);
    dts_Save.removeAll();
    txb_sel_isur_nm.setValue('');
    chb_insert_yn.setValue(0);
    scwin.fn_setHeader();
    var f_fn_search = $c.frame.path("../").fn_Search;
    f_fn_search();
    //frame.CloseFrame();

};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_setHeader();
};
